USE CorexProdDB;
GO

CREATE OR ALTER PROCEDURE dbo.USP_TES_TARJETA_PERIODO_GUARDAR
 @IdTarjetaPeriodo INT OUTPUT,@IdTarjetaCredito INT,@PeriodoAnio SMALLINT,@PeriodoMes TINYINT,@FechaCorte DATE,@FechaVencimiento DATE,
 @Monto DECIMAL(18,2)=NULL,@ImportePEN DECIMAL(18,2)=NULL,@ImporteUSD DECIMAL(18,2)=NULL,@Estado VARCHAR(30)=NULL,@Observacion VARCHAR(1000)='',@Usuario VARCHAR(80),
 @Resultado BIT OUTPUT,@Mensaje VARCHAR(500) OUTPUT,@TotalPagado DECIMAL(18,2) OUTPUT,@SaldoPendiente DECIMAL(18,2) OUTPUT,@EstadoPeriodo VARCHAR(30) OUTPUT
AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;SET @IdTarjetaPeriodo=ISNULL(@IdTarjetaPeriodo,0);SET @Resultado=0;SET @Mensaje='';SET @Usuario=LTRIM(RTRIM(ISNULL(@Usuario,'Sistema')));SET @Estado=NULLIF(UPPER(LTRIM(RTRIM(ISNULL(@Estado,'')))), '');
 IF @Usuario='' OR @PeriodoAnio NOT BETWEEN 2000 AND 2100 OR @PeriodoMes NOT BETWEEN 1 AND 12 OR @FechaCorte IS NULL OR @FechaVencimiento IS NULL OR @FechaVencimiento<@FechaCorte OR @ImportePEN<0 OR @ImporteUSD<0 BEGIN SET @Mensaje='Datos del periodo no validos.';RETURN END;
 BEGIN TRY BEGIN TRANSACTION;DECLARE @EstadoAnterior VARCHAR(30),@MonedaLegacy VARCHAR(10),@PagPEN DECIMAL(18,2)=0,@PagUSD DECIMAL(18,2)=0;
 SELECT @MonedaLegacy=Moneda FROM dbo.TesTarjetasCredito WITH(UPDLOCK,HOLDLOCK) WHERE IdTarjetaCredito=@IdTarjetaCredito AND Estado<>'ANULADA'; IF @MonedaLegacy IS NULL BEGIN ROLLBACK;SET @Mensaje='La tarjeta de credito no existe o esta anulada.';RETURN END;
 IF @IdTarjetaPeriodo>0 BEGIN SELECT @EstadoAnterior=Estado,@MonedaLegacy=Moneda FROM dbo.TesTarjetaCreditoPeriodos WITH(UPDLOCK,HOLDLOCK) WHERE IdTarjetaPeriodo=@IdTarjetaPeriodo AND IdTarjetaCredito=@IdTarjetaCredito;IF @EstadoAnterior IS NULL BEGIN ROLLBACK;SET @Mensaje='El periodo de tarjeta no existe.';RETURN END;IF @EstadoAnterior='ANULADA' BEGIN ROLLBACK;SET @Mensaje='No se puede editar un periodo anulado.';RETURN END;SELECT @PagPEN=ISNULL(SUM(CASE WHEN Estado='ACTIVO' AND Moneda='PEN' THEN Importe END),0),@PagUSD=ISNULL(SUM(CASE WHEN Estado='ACTIVO' AND Moneda='USD' THEN Importe END),0) FROM dbo.TesTarjetaCreditoPagos WHERE IdTarjetaPeriodo=@IdTarjetaPeriodo; END
 ELSE IF EXISTS(SELECT 1 FROM dbo.TesTarjetaCreditoPeriodos WHERE IdTarjetaCredito=@IdTarjetaCredito AND PeriodoAnio=@PeriodoAnio AND PeriodoMes=@PeriodoMes) BEGIN ROLLBACK;SET @Mensaje='Ya existe un periodo para la misma tarjeta, anio y mes.';RETURN END;
 IF @ImportePEN IS NULL AND @ImporteUSD IS NULL AND @Monto IS NOT NULL BEGIN IF @MonedaLegacy='USD' SET @ImporteUSD=@Monto ELSE SET @ImportePEN=@Monto END;
 IF @Estado IN ('PENDIENTE','PARCIAL','CANCELADA') AND @ImportePEN IS NULL AND @ImporteUSD IS NULL BEGIN ROLLBACK;SET @Mensaje='Un periodo exigible debe tener al menos un importe.';RETURN END;
 IF (@ImportePEN IS NULL AND @PagPEN>0) OR (@ImporteUSD IS NULL AND @PagUSD>0) OR (@ImportePEN IS NOT NULL AND @ImportePEN<@PagPEN) OR (@ImporteUSD IS NOT NULL AND @ImporteUSD<@PagUSD) BEGIN ROLLBACK;SET @Mensaje='No se puede reducir o eliminar una moneda con pagos activos.';RETURN END;
 DECLARE @SalP DECIMAL(18,2)=CASE WHEN @ImportePEN IS NULL THEN NULL ELSE @ImportePEN-@PagPEN END,@SalU DECIMAL(18,2)=CASE WHEN @ImporteUSD IS NULL THEN NULL ELSE @ImporteUSD-@PagUSD END,@EstP VARCHAR(30),@EstU VARCHAR(30);SET @EstP=CASE WHEN @ImportePEN IS NULL THEN NULL WHEN @SalP<=0 THEN 'CANCELADA' WHEN @PagPEN>0 THEN 'PARCIAL' ELSE 'PENDIENTE' END;SET @EstU=CASE WHEN @ImporteUSD IS NULL THEN NULL WHEN @SalU<=0 THEN 'CANCELADA' WHEN @PagUSD>0 THEN 'PARCIAL' ELSE 'PENDIENTE' END;SET @EstadoPeriodo=CASE WHEN @ImportePEN IS NULL AND @ImporteUSD IS NULL THEN 'ABIERTO' WHEN @EstP='PENDIENTE' OR @EstU='PENDIENTE' THEN 'PENDIENTE' WHEN @EstP='PARCIAL' OR @EstU='PARCIAL' THEN 'PARCIAL' ELSE 'CANCELADA' END;
 IF @IdTarjetaPeriodo=0 BEGIN INSERT dbo.TesTarjetaCreditoPeriodos(IdTarjetaCredito,PeriodoAnio,PeriodoMes,FechaCorte,FechaVencimiento,Moneda,Monto,TotalPagado,SaldoPendiente,Estado,Observacion,UsuarioCreacion,ImportePEN,ImporteUSD,TotalPagadoPEN,TotalPagadoUSD,SaldoPendientePEN,SaldoPendienteUSD,EstadoPEN,EstadoUSD) VALUES(@IdTarjetaCredito,@PeriodoAnio,@PeriodoMes,@FechaCorte,@FechaVencimiento,@MonedaLegacy,@Monto,0,@Monto,@EstadoPeriodo,@Observacion,@Usuario,@ImportePEN,@ImporteUSD,@PagPEN,@PagUSD,@SalP,@SalU,@EstP,@EstU);SET @IdTarjetaPeriodo=SCOPE_IDENTITY(); END ELSE UPDATE dbo.TesTarjetaCreditoPeriodos SET PeriodoAnio=@PeriodoAnio,PeriodoMes=@PeriodoMes,FechaCorte=@FechaCorte,FechaVencimiento=@FechaVencimiento,Monto=@Monto,TotalPagado=@PagPEN+@PagUSD,SaldoPendiente=CASE WHEN @ImportePEN IS NULL AND @ImporteUSD IS NULL THEN NULL ELSE ISNULL(@SalP,0)+ISNULL(@SalU,0) END,Estado=@EstadoPeriodo,Observacion=@Observacion,FechaModificacion=GETDATE(),UsuarioModificacion=@Usuario,ImportePEN=@ImportePEN,ImporteUSD=@ImporteUSD,TotalPagadoPEN=@PagPEN,TotalPagadoUSD=@PagUSD,SaldoPendientePEN=@SalP,SaldoPendienteUSD=@SalU,EstadoPEN=@EstP,EstadoUSD=@EstU WHERE IdTarjetaPeriodo=@IdTarjetaPeriodo;
 COMMIT;SET @Resultado=1;SET @Mensaje='Periodo de tarjeta guardado correctamente.';SET @TotalPagado=@PagPEN+@PagUSD;SET @SaldoPendiente=ISNULL(@SalP,0)+ISNULL(@SalU,0);END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK;SET @Mensaje=ERROR_MESSAGE();END CATCH;SELECT @Resultado Resultado,@Mensaje Mensaje,@IdTarjetaPeriodo IdTarjetaPeriodo,@TotalPagado TotalPagado,@SaldoPendiente SaldoPendiente,@EstadoPeriodo EstadoPeriodo;END;
GO

CREATE OR ALTER PROCEDURE dbo.USP_TES_TARJETA_PERIODO_LISTAR @IdTarjetaCredito INT=NULL,@Anio SMALLINT=NULL,@Estado VARCHAR(30)=NULL,@FechaDesde DATE=NULL,@FechaHasta DATE=NULL AS BEGIN SET NOCOUNT ON;SELECT P.*,T.Alias,T.Ultimos4,E.Nombre EntidadFinanciera,T.Titular,T.EmpresaResponsable FROM dbo.TesTarjetaCreditoPeriodos P JOIN dbo.TesTarjetasCredito T ON T.IdTarjetaCredito=P.IdTarjetaCredito JOIN dbo.TesEntidadesFinancieras E ON E.IdEntidadFinanciera=T.IdEntidadFinanciera WHERE (@IdTarjetaCredito IS NULL OR P.IdTarjetaCredito=@IdTarjetaCredito) AND (@Anio IS NULL OR P.PeriodoAnio=@Anio) AND (@Estado IS NULL OR P.Estado=@Estado) AND (@FechaDesde IS NULL OR P.FechaVencimiento>=@FechaDesde) AND (@FechaHasta IS NULL OR P.FechaVencimiento<=@FechaHasta) ORDER BY P.FechaVencimiento,E.Nombre,T.Alias;END;
GO

CREATE OR ALTER PROCEDURE dbo.USP_TES_TARJETA_PERIODO_OBTENER @IdTarjetaPeriodo INT AS BEGIN SET NOCOUNT ON;SELECT P.*,T.Alias,T.Ultimos4,E.Nombre EntidadFinanciera,T.Titular,T.EmpresaResponsable FROM dbo.TesTarjetaCreditoPeriodos P JOIN dbo.TesTarjetasCredito T ON T.IdTarjetaCredito=P.IdTarjetaCredito JOIN dbo.TesEntidadesFinancieras E ON E.IdEntidadFinanciera=T.IdEntidadFinanciera WHERE P.IdTarjetaPeriodo=@IdTarjetaPeriodo;SELECT PG.* ,B.Nombre Banco,CB.NombreCuenta FROM dbo.TesTarjetaCreditoPagos PG LEFT JOIN dbo.TesBancos B ON B.IdBanco=PG.IdBanco LEFT JOIN dbo.TesCuentasBancarias CB ON CB.IdCuentaBancaria=PG.IdCuentaBancaria WHERE PG.IdTarjetaPeriodo=@IdTarjetaPeriodo ORDER BY PG.FechaPago,PG.IdTarjetaPago;END;
GO

CREATE OR ALTER PROCEDURE dbo.USP_TES_TARJETA_REGISTRAR_PAGO @IdTarjetaPago INT OUTPUT,@IdTarjetaPeriodo INT,@FechaPago DATE,@IdBanco INT=NULL,@IdCuentaBancaria INT=NULL,@Importe DECIMAL(18,2),@Moneda VARCHAR(10),@NumeroOperacion VARCHAR(80)='',@Observacion VARCHAR(500)='',@Usuario VARCHAR(80),@Resultado BIT OUTPUT,@Mensaje VARCHAR(500) OUTPUT,@TotalPagado DECIMAL(18,2) OUTPUT,@SaldoPendiente DECIMAL(18,2) OUTPUT,@EstadoPeriodo VARCHAR(30) OUTPUT AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;SET @Resultado=0;SET @Moneda=UPPER(LTRIM(RTRIM(ISNULL(@Moneda,''))));IF @Moneda NOT IN('PEN','USD') OR @Importe<=0 OR @FechaPago IS NULL BEGIN SET @Mensaje='Datos de pago no validos.';RETURN END;BEGIN TRY BEGIN TRANSACTION;DECLARE @P DECIMAL(18,2),@U DECIMAL(18,2),@TP DECIMAL(18,2),@TU DECIMAL(18,2),@SP DECIMAL(18,2),@SU DECIMAL(18,2),@EP VARCHAR(30),@EU VARCHAR(30),@IdTarjeta INT,@Estado VARCHAR(30);SELECT @IdTarjeta=P.IdTarjetaCredito,@Estado=P.Estado,@P=P.ImportePEN,@U=P.ImporteUSD,@TP=P.TotalPagadoPEN,@TU=P.TotalPagadoUSD FROM dbo.TesTarjetaCreditoPeriodos P WITH(UPDLOCK,HOLDLOCK) WHERE P.IdTarjetaPeriodo=@IdTarjetaPeriodo;IF @IdTarjeta IS NULL OR @Estado IN('ABIERTO','ANULADA') OR (@Moneda='PEN' AND @P IS NULL) OR (@Moneda='USD' AND @U IS NULL) BEGIN ROLLBACK;SET @Mensaje='El periodo no permite pagos para la moneda indicada.';RETURN END;IF @Importe>CASE WHEN @Moneda='PEN' THEN @P-@TP ELSE @U-@TU END BEGIN ROLLBACK;SET @Mensaje='El importe supera el saldo pendiente de la moneda.';RETURN END;INSERT dbo.TesTarjetaCreditoPagos(IdTarjetaPeriodo,FechaPago,IdBanco,IdCuentaBancaria,Importe,Moneda,NumeroOperacion,Observacion,Estado,UsuarioCreacion) VALUES(@IdTarjetaPeriodo,@FechaPago,@IdBanco,@IdCuentaBancaria,@Importe,@Moneda,@NumeroOperacion,@Observacion,'ACTIVO',@Usuario);SET @IdTarjetaPago=SCOPE_IDENTITY();SELECT @TP=ISNULL(SUM(CASE WHEN Estado='ACTIVO' AND Moneda='PEN' THEN Importe END),0),@TU=ISNULL(SUM(CASE WHEN Estado='ACTIVO' AND Moneda='USD' THEN Importe END),0) FROM dbo.TesTarjetaCreditoPagos WHERE IdTarjetaPeriodo=@IdTarjetaPeriodo;SET @SP=CASE WHEN @P IS NULL THEN NULL ELSE @P-@TP END;SET @SU=CASE WHEN @U IS NULL THEN NULL ELSE @U-@TU END;SET @EP=CASE WHEN @P IS NULL THEN NULL WHEN @SP<=0 THEN 'CANCELADA' WHEN @TP>0 THEN 'PARCIAL' ELSE 'PENDIENTE' END;SET @EU=CASE WHEN @U IS NULL THEN NULL WHEN @SU<=0 THEN 'CANCELADA' WHEN @TU>0 THEN 'PARCIAL' ELSE 'PENDIENTE' END;SET @EstadoPeriodo=CASE WHEN @EP='PENDIENTE' OR @EU='PENDIENTE' THEN 'PENDIENTE' WHEN @EP='PARCIAL' OR @EU='PARCIAL' THEN 'PARCIAL' ELSE 'CANCELADA' END;UPDATE dbo.TesTarjetaCreditoPeriodos SET TotalPagadoPEN=@TP,TotalPagadoUSD=@TU,SaldoPendientePEN=@SP,SaldoPendienteUSD=@SU,EstadoPEN=@EP,EstadoUSD=@EU,Estado=@EstadoPeriodo,FechaModificacion=GETDATE(),UsuarioModificacion=@Usuario WHERE IdTarjetaPeriodo=@IdTarjetaPeriodo;COMMIT;SET @Resultado=1;SET @Mensaje='Pago de tarjeta registrado correctamente.';SET @TotalPagado=@TP+@TU;SET @SaldoPendiente=ISNULL(@SP,0)+ISNULL(@SU,0);END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK;SET @Mensaje=ERROR_MESSAGE();END CATCH;SELECT @Resultado Resultado,@Mensaje Mensaje,@IdTarjetaPago IdTarjetaPago,@TotalPagado TotalPagado,@SaldoPendiente SaldoPendiente,@EstadoPeriodo EstadoPeriodo;END;
GO

CREATE OR ALTER PROCEDURE dbo.USP_TES_TARJETA_ANULAR_PAGO @IdTarjetaPago INT,@Usuario VARCHAR(80),@Motivo VARCHAR(500),@Resultado BIT OUTPUT,@Mensaje VARCHAR(500) OUTPUT,@TotalPagado DECIMAL(18,2) OUTPUT,@SaldoPendiente DECIMAL(18,2) OUTPUT,@EstadoPeriodo VARCHAR(30) OUTPUT AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;SET @Resultado=0;BEGIN TRY BEGIN TRANSACTION;DECLARE @I INT,@P DECIMAL(18,2),@U DECIMAL(18,2),@TP DECIMAL(18,2),@TU DECIMAL(18,2),@SP DECIMAL(18,2),@SU DECIMAL(18,2),@EP VARCHAR(30),@EU VARCHAR(30),@E VARCHAR(30);SELECT @I=PG.IdTarjetaPeriodo FROM dbo.TesTarjetaCreditoPagos PG WITH(UPDLOCK,HOLDLOCK) WHERE PG.IdTarjetaPago=@IdTarjetaPago AND PG.Estado='ACTIVO';IF @I IS NULL BEGIN ROLLBACK;SET @Mensaje='El pago seleccionado no existe o ya se encuentra anulado.';RETURN END;SELECT @P=ImportePEN,@U=ImporteUSD,@E=Estado FROM dbo.TesTarjetaCreditoPeriodos WITH(UPDLOCK,HOLDLOCK) WHERE IdTarjetaPeriodo=@I;IF @E='ANULADA' BEGIN ROLLBACK;SET @Mensaje='No se puede anular pagos de un periodo anulado.';RETURN END;UPDATE dbo.TesTarjetaCreditoPagos SET Estado='ANULADO',FechaAnulacion=GETDATE(),UsuarioAnulacion=@Usuario,MotivoAnulacion=@Motivo WHERE IdTarjetaPago=@IdTarjetaPago;SELECT @TP=ISNULL(SUM(CASE WHEN Estado='ACTIVO' AND Moneda='PEN' THEN Importe END),0),@TU=ISNULL(SUM(CASE WHEN Estado='ACTIVO' AND Moneda='USD' THEN Importe END),0) FROM dbo.TesTarjetaCreditoPagos WHERE IdTarjetaPeriodo=@I;SET @SP=CASE WHEN @P IS NULL THEN NULL ELSE @P-@TP END;SET @SU=CASE WHEN @U IS NULL THEN NULL ELSE @U-@TU END;SET @EP=CASE WHEN @P IS NULL THEN NULL WHEN @SP<=0 THEN 'CANCELADA' WHEN @TP>0 THEN 'PARCIAL' ELSE 'PENDIENTE' END;SET @EU=CASE WHEN @U IS NULL THEN NULL WHEN @SU<=0 THEN 'CANCELADA' WHEN @TU>0 THEN 'PARCIAL' ELSE 'PENDIENTE' END;SET @EstadoPeriodo=CASE WHEN @EP='PENDIENTE' OR @EU='PENDIENTE' THEN 'PENDIENTE' WHEN @EP='PARCIAL' OR @EU='PARCIAL' THEN 'PARCIAL' ELSE 'CANCELADA' END;UPDATE dbo.TesTarjetaCreditoPeriodos SET TotalPagadoPEN=@TP,TotalPagadoUSD=@TU,SaldoPendientePEN=@SP,SaldoPendienteUSD=@SU,EstadoPEN=@EP,EstadoUSD=@EU,Estado=@EstadoPeriodo WHERE IdTarjetaPeriodo=@I;COMMIT;SET @Resultado=1;SET @Mensaje='Pago de tarjeta anulado correctamente.';SET @TotalPagado=@TP+@TU;SET @SaldoPendiente=ISNULL(@SP,0)+ISNULL(@SU,0);END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK;SET @Mensaje=ERROR_MESSAGE();END CATCH;SELECT @Resultado Resultado,@Mensaje Mensaje,@IdTarjetaPago IdTarjetaPago,@TotalPagado TotalPagado,@SaldoPendiente SaldoPendiente,@EstadoPeriodo EstadoPeriodo;END;
GO
